package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation walked the input one byte at a time with a
// shared state machine (header level, list depth, and several boolean
// flags), which made its behavior hard to follow. The rewrite processes
// the document line by line instead, because every markdown construct in
// this exercise (headers, list items, paragraphs) is line-oriented:
//
//   - Emphasis (__bold__ / _italic_) is substituted up front, so it also
//     works inside headers and list items, as the original code did.
//   - Each line is then rendered independently as a header, a list item,
//     or a paragraph; a <ul> is opened on the first list item and closed
//     when the list ends (a non-list line or end of input).
//
// This removes the need for the original's byte offsets, the "header
// encountered" flag, and the LastIndex-based check for a line following
// the list.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var html strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		switch {
		case strings.HasPrefix(line, "#"):
			html.WriteString(renderHeader(line))
		case strings.HasPrefix(line, "*"):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + strings.TrimPrefix(line, "* ") + "</li>")
		default:
			if inList {
				html.WriteString("</ul>")
				inList = false
			}
			html.WriteString("<p>" + line + "</p>")
		}
	}

	if inList {
		html.WriteString("</ul>")
	}

	return html.String()
}

// applyEmphasis replaces bold and italic markers with their HTML tags.
// "__" must be replaced before "_" so that bold markers are not
// mistaken for a pair of italic markers.
func applyEmphasis(markdown string) string {
	markdown = strings.ReplaceAll(markdown, "__", "<strong>")
	return strings.ReplaceAll(markdown, "_", "<em>")
}

// renderHeader renders a line that starts with one or more '#'.
// Up to six '#' produce an h1-h6 header; seven or more '#' are not a
// valid header level, so the line is rendered as a plain paragraph
// with the '#' characters left in place.
func renderHeader(line string) string {
	level := 0
	for strings.HasPrefix(line, "#") {
		line = line[1:]
		level++
	}
	if level > 6 {
		return "<p>" + strings.Repeat("#", level) + line + "</p>"
	}
	// The single space after the '#' markers is not part of the header text.
	line = strings.TrimPrefix(line, " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, line, level)
}

